+fn valid_repo_part(part: &str) -> bool {
+    !part.is_empty() && part.bytes().all(|byte| byte.is_ascii_alphanumeric() || matches!(byte, b'-' | b'_' | b'.'))
+}
+
+fn validate_branch(kind: &'static str, branch: &str) -> Result<(), ReleasePrDecisionError> {
+    let valid = !branch.is_empty()
+        && !branch.starts_with('-')
+        && !branch.starts_with('/')
+        && !branch.ends_with('/')
+        && !branch.contains("//")
+        && !branch.contains("..")
+        && !branch.contains("@{")
+        && branch != "@"
+        && branch.split('/').all(|part| !part.starts_with('.') && !part.ends_with(".lock"))
+        && branch.chars().all(|ch| !ch.is_ascii_control() && !ch.is_whitespace() && !matches!(ch, '~' | '^' | ':' | '?' | '*' | '[' | '\\'));
+    if valid {
+        Ok(())
+    } else {
+        Err(ReleasePrDecisionError::InvalidBranch {
+            kind,
+            branch: branch.to_string(),
+        })
+    }
