+        return Ok(None);
+    };
+    if suffix.len() == 40 && suffix.bytes().all(|byte| byte.is_ascii_digit() || matches!(byte, b'a'..=b'f')) {
+        Ok(Some(()))
+    } else {
+        Err(ReleasePrDecisionError::MalformedManagedBranch {
+            branch: branch.to_string(),
+        })
+    }
+}
